STRUCT System {
  FIELD state: [INIT, ACTIVE, HALT]
  FIELD depth: 0..4
  FIELD registry: MAP<Symbol, Value>

  FUNC initialize() {
    state := INIT
    depth := 0
    registry := {}
  }

  FUNC execute(input: Notation) {
    IF state == INIT THEN
      state := ACTIVE
      depth := 0
    ENDIF

    LOOP WHILE state == ACTIVE AND depth < 4 {
      MATCH input {
        CASE Struct(name, fields) {
          registry[name] := fields
          depth := depth + 1
        }
        CASE Loop(cond, body) {
          WHILE evaluate(cond) {
            execute(body)
            depth := depth + 1
          }
        }
        CASE Conditional(test, consequent, alternate) {
          IF evaluate(test) THEN
            execute(consequent)
          ELSE
            execute(alternate)
          ENDIF
        }
        CASE Function(sig, impl) {
          registry[sig.name] := impl
        }
        CASE Sequence(items) {
          FOR item IN items {
            execute(item)
          }
        }
        CASE Null {
          state := HALT
        }
      }
    }
  }

  FUNC evaluate(expr: Expression): Boolean {
    RETURN match_constraints(expr, registry)
  }
}

